<?php if(!$appointmentRows): ?><div class="empty-state"><i class="bi bi-calendar2" aria-hidden="true"></i><p>Bu bölümde henüz randevunuz yok.</p><a class="btn btn-outline-dark" href="<?= e(url('customer/book')) ?>">İlk randevunuzu planlayın</a></div><?php else: ?><div class="customer-appointment-list"><?php foreach($appointmentRows as $row): ?><article class="customer-appointment"><div class="appointment-date"><strong><?= e(date('d',strtotime($row['start_at']))) ?></strong><span><?= e(date('m.Y',strtotime($row['start_at']))) ?></span></div><div class="appointment-copy"><h3><?= e($row['service_name']) ?></h3><p><?= e($row['employee_name']) ?> · <?= e(date('H:i',strtotime($row['start_at']))) ?>–<?= e(date('H:i',strtotime($row['end_at']))) ?></p><small>#<?= (int)$row['id'] ?> · <?= e($money($row['service_price'])) ?></small></div><div class="appointment-actions"><span class="status-pill status-<?= e($row['status']) ?>"><?= e($labels[$row['status']]) ?></span><a class="btn btn-sm btn-outline-dark" href="<?= e(url('customer/appointments/detail?id='.$row['id'])) ?>">Detayı gör</a></div></article><?php endforeach ?></div><?php endif ?>
